(function() {
  var _sentiment = '';

  window.openFeedbackBox = function(type) {
    _sentiment = type;
    var box    = document.getElementById('feedbackBox');
    var title  = document.getElementById('feedbackBoxTitle');
    var btnYes = document.querySelector('.feedback-widget__btn--yes');
    var btnNo  = document.querySelector('.feedback-widget__btn--no');

    if (window.plausible) plausible('Feedback', { props: { type: type === 'yes' ? 'like' : 'dislike', page: 'warsaw' } });

    title.textContent = type === 'yes'
      ? 'תודה רבה על הפידבק, אשמח לשמוע מה אהבת'
      : 'תודה רבה על הפידבק, אשמח לדעת במה נוכל להשתפר באתר';

    box.classList.add('open');

    if (window.twemoji) {
      twemoji.parse(title, { folder: 'svg', ext: '.svg', base: 'https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/' });
    }

    btnYes.classList.toggle('dimmed', type !== 'yes');
    btnNo.classList.toggle('dimmed',  type !== 'no');

    setTimeout(function() { box.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }, 100);
  };

  window.sendFeedback = function() {
    var text = document.getElementById('feedbackText').value.trim();
    var btn  = document.getElementById('feedbackSendBtn');

    btn.textContent = 'שולח...';
    btn.disabled = true;

    fetch('https://formspree.io/f/mrejrqea', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({
        sentiment: _sentiment === 'yes' ? '👍 חיובי' : '👎 שלילי',
        message:   text || '(ללא הודעה)',
        page:      'warsaw'
      })
    })
    .then(function(res) {
      if (!res.ok) throw new Error('שגיאה');
      if (window.plausible) plausible('Feedback Sent', { props: { type: _sentiment === 'yes' ? 'like' : 'dislike', page: 'warsaw' } });
      document.getElementById('feedbackSendBtn').style.display  = 'none';
      document.getElementById('feedbackText').style.display     = 'none';
      document.getElementById('feedbackBoxTitle').style.display = 'none';
      document.getElementById('feedbackThanks').style.display   = 'block';
    })
    .catch(function() {
      btn.textContent = 'שליחה ←';
      btn.disabled = false;
      alert('אירעה שגיאה, נסו שוב.');
    });
  };
})();

