(function () {
  var sectionIds = ['intro','route-map','itinerary','theme-parks-warsaw','accommodation','airport-stay','logistics'];
  var activeId = null;

  var stoc = document.getElementById('stoc');
  var desktopLinks = {};
  if (stoc) {
    sectionIds.forEach(function(id){ var el=stoc.querySelector('[data-stoc="'+id+'"]'); if(el) desktopLinks[id]=el; });
    function checkDesktopVisible(){ if(window.scrollY>300){ stoc.classList.add('stoc--visible'); window.removeEventListener('scroll',checkDesktopVisible); } }
    window.addEventListener('scroll',checkDesktopVisible,{passive:true});
    checkDesktopVisible();
  }

  var fab=document.getElementById('stocFab'), sheet=document.getElementById('stocSheet'), fabBadge=document.getElementById('stocFabBadge');
  var mobileLinks={};
  if(fab){ function checkFab(){ if(window.scrollY>280){ fab.classList.add('stoc-fab--visible'); window.removeEventListener('scroll',checkFab); } } window.addEventListener('scroll',checkFab,{passive:true}); checkFab(); }
  if(sheet){
    sectionIds.forEach(function(id){ var el=sheet.querySelector('[data-stoc-m="'+id+'"]'); if(el) mobileLinks[id]=el; });
    function openSheet(){ sheet.classList.add('stoc-sheet--open'); if(fab) fab.setAttribute('aria-expanded','true'); document.body.style.overflow='hidden'; }
    function closeSheet(){ sheet.classList.remove('stoc-sheet--open'); if(fab) fab.setAttribute('aria-expanded','false'); document.body.style.overflow=''; }
    if(fab) fab.addEventListener('click',openSheet);
    var btnClose=document.getElementById('stocSheetClose'), backdrop=document.getElementById('stocSheetBackdrop');
    if(btnClose) btnClose.addEventListener('click',closeSheet);
    if(backdrop) backdrop.addEventListener('click',closeSheet);
    sheet.querySelectorAll('.stoc-sheet__link').forEach(function(l){ l.addEventListener('click',function(){ setTimeout(closeSheet,120); }); });
    document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&sheet.classList.contains('stoc-sheet--open')) closeSheet(); });
  }

  function setActive(id){
    if(id===activeId) return;
    if(activeId&&desktopLinks[activeId]) desktopLinks[activeId].classList.remove('stoc--active');
    if(id&&desktopLinks[id]) desktopLinks[id].classList.add('stoc--active');
    if(activeId&&mobileLinks[activeId]) mobileLinks[activeId].classList.remove('stoc--active');
    if(id&&mobileLinks[id]) mobileLinks[id].classList.add('stoc--active');
    var idx=sectionIds.indexOf(id); if(fabBadge&&idx!==-1) fabBadge.textContent=idx+1;
    activeId=id;
  }
  var observer=new IntersectionObserver(function(entries){
    var visible=entries.filter(function(e){return e.isIntersecting;});
    if(visible.length){ visible.sort(function(a,b){return a.boundingClientRect.top-b.boundingClientRect.top;}); setActive(visible[0].target.id); }
  },{rootMargin:'-10% 0px -60% 0px',threshold:0});
  sectionIds.forEach(function(id){ var el=document.getElementById(id); if(el) observer.observe(el); });
})();
